@props(['variant' => 'outline'])

@php
    if ($variant !== 'outline') {
        throw new \Exception('The supplied financial dashboard icon supports the outline variant only.');
    }

    $classes = Flux::classes('inline-block shrink-0 bg-current align-middle')->add('[:where(&)]:size-6');
    $iconMask = 'data:image/png;base64,';
@endphp

<span
    {{ $attributes->class($classes) }}
    data-flux-icon
    data-slot="icon"
    data-finance-icon="exact-supplied-rising-bars-arrow"
    data-finance-style="theme-colored-original-silhouette"
    aria-hidden="true"
    style="-webkit-mask: url('{{ $iconMask }}') center / contain no-repeat; mask: url('{{ $iconMask }}') center / contain no-repeat; transform: translateY(-1px);"
></span>
